// Marketing: segments, campaigns, offers, attribution.
// Owner: Agent C (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { isoDate, isoDateTime, minor, optionalText, text, uuid } from './common';

export const marketingContractsVersion = 1 as const;

// ---------------------------------------------------------------------------
// Segment rule DSL. Compiled server-side to parameterised SQL over customers;
// values are always bound parameters, never interpolated.
// ---------------------------------------------------------------------------
const withinDays = z.number().int().min(1).max(3650).optional();
export const SEGMENT_ORDER_CHANNELS = ['qr', 'web', 'whatsapp', 'staff', 'pos', 'mcp', 'phone'] as const;

export const segmentRule = z.discriminatedUnion('type', [
  /** No (non-cancelled) order and no visit for at least N days. */
  z.object({ type: z.literal('inactive_days_gte'), days: z.number().int().min(1).max(3650) }).strict(),
  z.object({ type: z.literal('orders_gte'), count: z.number().int().min(1).max(100000), withinDays }).strict(),
  z.object({ type: z.literal('spent_gte'), amountMinor: minor, withinDays }).strict(),
  z.object({ type: z.literal('has_tag'), tag: z.string().trim().min(1).max(40) }).strict(),
  z.object({ type: z.literal('consent'), value: z.boolean() }).strict(),
  /** Has ordered at this branch. */
  z.object({ type: z.literal('branch'), branchId: uuid }).strict(),
  z.object({ type: z.literal('purchased_product'), productId: uuid, withinDays }).strict(),
  /** Has ordered through this channel. */
  z.object({ type: z.literal('channel'), channel: z.enum(SEGMENT_ORDER_CHANNELS) }).strict(),
]);
export type SegmentRule = z.infer<typeof segmentRule>;

export interface SegmentGroup {
  op: 'and' | 'or';
  rules: Array<SegmentRule | SegmentGroup>;
}

export const segmentGroup: z.ZodType<SegmentGroup> = z.lazy(() =>
  z.object({ op: z.enum(['and', 'or']), rules: z.array(z.union([segmentRule, segmentGroup])).min(1).max(20) }).strict());

export const SEGMENT_MAX_DEPTH = 3;
export const SEGMENT_MAX_RULES = 30;

function measure(g: SegmentGroup, depth = 1): { depth: number; rules: number } {
  let d = depth, n = 0;
  for (const r of g.rules) {
    if ('op' in r) {
      const m = measure(r, depth + 1);
      d = Math.max(d, m.depth);
      n += m.rules;
    } else n += 1;
  }
  return { depth: d, rules: n };
}

export const segmentDefinition = segmentGroup.superRefine((g, ctx) => {
  const m = measure(g);
  if (m.depth > SEGMENT_MAX_DEPTH) ctx.addIssue({ code: 'custom', message: `Nest groups at most ${SEGMENT_MAX_DEPTH} levels deep` });
  if (m.rules > SEGMENT_MAX_RULES) ctx.addIssue({ code: 'custom', message: `At most ${SEGMENT_MAX_RULES} rules per segment` });
});

export const segmentInput = z.object({
  name: text(80),
  description: optionalText(300),
  definition: segmentDefinition,
}).strict();
export type SegmentInput = z.infer<typeof segmentInput>;
export const segmentUpdate = z.object({ name: text(80).optional(), description: optionalText(300), definition: segmentDefinition.optional() }).strict();
export const segmentPreview = z.object({ definition: segmentDefinition }).strict();

// ---------------------------------------------------------------------------
// Promotions (the kernel PricingService applies them at checkout)
// ---------------------------------------------------------------------------
const promotionBase = z.object({
  code: z.string().trim().regex(/^[A-Za-z0-9_-]{3,32}$/, '3–32 letters, digits, - or _').nullable().optional(),
  name: text(80),
  nameAr: optionalText(80),
  kind: z.enum(['percent', 'fixed', 'free_delivery']),
  /** Basis points for percent (1000 = 10%), minor units for fixed, 0 for free delivery. */
  value: z.number().int().min(0).max(1e9),
  maxDiscountMinor: minor.nullable().optional(),
  minOrderMinor: minor.default(0),
  branchIds: z.array(uuid).max(100).nullable().optional(),
  channels: z.array(z.enum(SEGMENT_ORDER_CHANNELS)).max(7).nullable().optional(),
  startsAt: isoDateTime.nullable().optional(),
  endsAt: isoDateTime.nullable().optional(),
  maxRedemptions: z.number().int().min(1).max(1e7).nullable().optional(),
  perCustomerLimit: z.number().int().min(1).max(1000).nullable().optional(),
  isActive: z.boolean().default(true),
}).strict();
export const promotionInput = promotionBase.superRefine((p, ctx) => {
  if (p.kind === 'percent' && (p.value < 1 || p.value > 10000)) ctx.addIssue({ code: 'custom', path: ['value'], message: 'Percent offers are 1–10000 basis points' });
  if (p.kind === 'fixed' && p.value < 1) ctx.addIssue({ code: 'custom', path: ['value'], message: 'Fixed discounts must be positive' });
  if (p.startsAt && p.endsAt && p.endsAt <= p.startsAt) ctx.addIssue({ code: 'custom', path: ['endsAt'], message: 'End must be after start' });
});
export type PromotionInput = z.infer<typeof promotionInput>;
export const promotionUpdate = promotionBase.partial().strict();

// ---------------------------------------------------------------------------
// Campaigns
// ---------------------------------------------------------------------------
export const CAMPAIGN_CHANNELS = ['whatsapp', 'sms', 'email', 'meta_ads', 'tiktok_ads', 'snapchat_ads', 'organic'] as const;
export type CampaignChannel = (typeof CAMPAIGN_CHANNELS)[number];
export const AD_CHANNELS: readonly CampaignChannel[] = ['meta_ads', 'tiktok_ads', 'snapchat_ads'];
export const MESSAGE_CHANNELS: readonly CampaignChannel[] = ['whatsapp', 'sms'];
export const CAMPAIGN_OBJECTIVES = ['retention', 'reactivation', 'acquisition', 'upsell', 'awareness', 'reservations'] as const;
export const CAMPAIGN_STATUSES = ['draft', 'pending_approval', 'approved', 'scheduled', 'sending', 'launching', 'sent', 'cancelled', 'failed'] as const;
export type CampaignStatus = (typeof CAMPAIGN_STATUSES)[number];

export const campaignContent = z.object({
  /** Free-form body (only deliverable inside the 24-hour window on WhatsApp). */
  text: z.string().trim().max(1024).optional(),
  /** Approved WhatsApp template (required to reach customers outside the window). */
  templateName: z.string().regex(/^[a-z0-9_]{1,512}$/).optional(),
  variables: z.array(z.string().max(200)).max(10).optional(),
  /** Path on the restaurant site for tracking links, e.g. "/order/my-slug". */
  landingPath: z.string().regex(/^\/(?!\/)[^\s]*$/).max(300).optional(),
  headline: z.string().trim().max(120).optional(),
}).strict();

/**
 * Ad launch (INT-14): 'live' needs a connected live ad account for the campaign's channel; 'sandbox' is an explicit
 * rehearsal on the ads sandbox. A live account that exists but is unhealthy is never replaced by the sandbox.
 */
export const launchCampaign = z.object({ mode: z.enum(['live', 'sandbox']).default('live') }).strict().default({ mode: 'live' });
export type LaunchCampaign = z.infer<typeof launchCampaign>;
/** Clears a launch whose outcome is unknown, after the owner checked the provider for the tagged campaign (PS-14). */
export const resetCampaignLaunch = z.object({ confirmNotCreated: z.literal(true) }).strict();

export const campaignInput = z.object({
  name: text(120),
  objective: z.enum(CAMPAIGN_OBJECTIVES).default('retention'),
  channel: z.enum(CAMPAIGN_CHANNELS),
  segmentId: uuid.nullable().optional(),
  promotionId: uuid.nullable().optional(),
  content: campaignContent.default({}),
  budgetMinor: minor.nullable().optional(),
}).strict();
export type CampaignInput = z.infer<typeof campaignInput>;
export const campaignUpdate = campaignInput.partial().strict();
export const scheduleCampaign = z.object({ scheduledAt: isoDateTime }).strict();
export const rejectCampaign = z.object({ reason: optionalText(300) }).strict();
export const adInsightsSync = z.object({ since: isoDate, until: isoDate }).strict()
  .refine((v) => v.until >= v.since, { message: 'until must not be before since' });

// ---------------------------------------------------------------------------
// Tracking links and attribution
// ---------------------------------------------------------------------------
const utmPart = z.string().trim().max(100).regex(/^[\w.\-~ %+:]*$/).optional();
export const trackingLinkInput = z.object({
  campaignId: uuid.nullable().optional(),
  /** Relative path only (open redirects are impossible): "/order/slug?x=1". */
  destinationPath: z.string().max(500).regex(/^\/(?!\/)[A-Za-z0-9\-._~!$&'()*+,;=:@%/?]*$/, 'a path on this site starting with /'),
  utm: z.object({ source: utmPart, medium: utmPart, campaign: utmPart, content: utmPart, term: utmPart }).strict().default({}),
}).strict();
export type TrackingLinkInput = z.infer<typeof trackingLinkInput>;

export const ATTRIBUTION_DISCLAIMER =
  'Last-touch attribution: an order counts for a campaign when the customer’s most recent tracked touch (link click or campaign message) came from it. ' +
  'This is correlation, not incremental lift — some of these customers would have ordered anyway.';

export interface CampaignReport {
  campaignId: string;
  model: 'last_touch';
  disclaimer: string;
  currency: string;
  clicks: number;
  messages: { sent: number; delivered: number; read: number; failed: number; skippedNoConsent: number };
  orders: number;
  revenueMinor: number;
  /** Ad spend from non-sandbox provider reports only. */
  costMinor: number;
  sandboxRowsExcluded: number;
  roas: number | null;
  isSandbox: boolean;
}

export interface MarketingRecommendation {
  key: string;
  title: string;
  titleAr: string;
  rationale: string;
  /** Deterministic evidence the recommendation is based on (counts, rules). */
  evidence: Record<string, unknown>;
  action: { kind: 'create_campaign_draft'; channel: CampaignChannel; objective: (typeof CAMPAIGN_OBJECTIVES)[number]; segmentDefinition: SegmentGroup } | { kind: 'none' };
}
